B64
tar xzf "$DST/v458.tgz" -C "$DST" && rm "$DST/v458.tgz"
sha256sum -c - <<SUMS
4ee4b26068ac9b07c596a83efd41815c600f7596dab57dc7b72235ac3bb71e35  $DST/order-voice-bot/server-layout.cjs
253a9f822dc3a166005fc7d611a0fa0a508539722b0a806e2eddbe1752905793  $DST/order-voice-bot/server-layout.test.cjs
3ed37964935349c2cf57cd308e6850fae26bef7972d673cefa60ba343af85a6f  $DST/order-voice-bot/guide-channel.cjs
4ee79a7dfc986de76286ed7722aa65ef8a3e8b09510660aa4c72eae5a91580b0  $DST/order-voice-bot/guide-channel.test.cjs
a0e2d47640e129b17b524a6519db865ceb5dd7464d876eb1502da91eae4c95a5  $DST/order-voice-bot/assets/guide-banner.gif
403f8ca306276e7cf3fb0d934850bd6c42f23faf1ee999281683c7df85a5880f  $DST/order-voice-bot/party-discord.cjs
ea80524573459539dacde52d9359c23200dccfaca910f1da615b5d50dbb5971d  $DST/order-voice-bot/member-lounge.cjs
b2fe7db7d77158021cf86f34ccdf8bf2ee3468a9d2fa0ba58a28094b09b690f7  $DST/order-voice-bot/member-lounge.test.cjs
5bd29db323b4db17a52d61975b938825316f5b5bcba0a5a1f2e129d33b8fa40e  $DST/order-voice-bot/service-server.cjs
SUMS
if [ -n "$R" ]; then echo "TEST_ROOT: 檔案準備完成"; exit 0; fi
say "建置 docker 映像（約 1～3 分鐘）"
cd "$DST"
docker build -t tinytavern-service:$TAG . > build.log 2>&1 || { tail -20 build.log; echo "建置失敗，正式服務沒有變動。"; exit 1; }
for f in order-voice-bot/server-layout.cjs order-voice-bot/guide-channel.cjs order-voice-bot/member-lounge.cjs order-voice-bot/party-discord.cjs order-voice-bot/service-server.cjs; do docker run --rm --network none --entrypoint node tinytavern-service:$TAG --check $f; done
docker run --rm --network none --entrypoint node tinytavern-service:$TAG --test order-voice-bot/member-lounge.test.cjs order-voice-bot/guide-channel.test.cjs order-voice-bot/server-layout.test.cjs order-voice-bot/member-roles.test.cjs order-voice-bot/counter-desk.test.cjs order-voice-bot/party.test.cjs order-voice-bot/party-flow.test.cjs order-voice-bot/voice-open.test.cjs order-voice-bot/staff-names.test.cjs > test.log 2>&1 || { tail -20 test.log; echo "測試失敗，正式服務沒有變動。"; exit 1; }
docker run --rm --network none --entrypoint node tinytavern-service:$TAG order-voice-bot/vip-outfit.test.cjs >> test.log 2>&1 || { tail -20 test.log; echo "測試失敗，正式服務沒有變動。"; exit 1; }
cp -p "$UNIT" "$UNIT.before-v458"
rollback(){ say "健康檢查失敗，還原舊版"; cp -p "$UNIT.before-v458" "$UNIT"; systemctl daemon-reload; systemctl restart tinytavern-service; echo "已還原為 $CUR。"; exit 1; }
say "切換到新版本並重啟"
sed -i "s/tinytavern-service:$CUR/tinytavern-service:$TAG/" "$UNIT"
systemctl daemon-reload
systemctl restart tinytavern-service
for i in $(seq 1 30); do
  sleep 2
  systemctl is-active --quiet tinytavern-service || continue
  L=$(docker logs --since 2m tinytavern-service 2>&1)
  echo "$L" | grep -q '^ORDER_NOTIFY_READY$' || continue
  echo "$L" | grep -q '^ROLES_STARTED$' || continue
  echo "$L" | grep -q '^COUNTER_STARTED$' || continue
  a=$(curl -s -o /dev/null -w '%{http_code}' -X POST -H 'Content-Type: application/json' -d '{}' http://127.0.0.1:8081/v1/voice/session || true)
  b=$(curl -s -o /dev/null -w '%{http_code}' -X POST -H 'Content-Type: application/json' -d '{}' http://127.0.0.1:8081/v1/rooms/session || true)
  c=$(curl -s -o /dev/null -w '%{http_code}' -X POST -H 'Content-Type: application/json' -d '{}' http://127.0.0.1:8081/v1/voice/vip-outfit || true)
  if [ "$a" = 401 ] && [ "$b" = 401 ] && [ "$c" = 401 ]; then
    say "V458_DEPLOYED_AND_HEALTHY"
    sleep 15; echo "機器人狀態："; docker logs --since 2m tinytavern-service 2>&1 | grep -E '^(LAYOUT_|LOUNGE_|GUIDE_|ROLES_|COUNTER_)' | grep -v STARTED | tail -14
    exit 0
  fi
  last="session=$a rooms=$b vip=$c"
done
echo "健康檢查結果：${last:-服務未就緒}"
docker logs --since 3m tinytavern-service 2>&1 | tail -20
rollback
